/*
 * The three sources, and how much of the label space each one can actually speak to.
 *
 * This is the whole engineering story of the project. Combining datasets does not combine their
 * label semantics: CheXpert supplies seven of the fourteen findings and says nothing about the
 * rest, the pneumonia set supplies exactly one, and only NIH covers all fourteen. Treating the
 * silence as a negative would teach the model that every CheXpert chest is free of emphysema,
 * fibrosis, hernia and the rest - so the silence is masked out instead.
 */
export const sources = [
  { key: "chexpert", name: "CheXpert", approxImages: "223K", labelled: 7, labels: ["Atelectasis", "Cardiomegaly", "Consolidation", "Edema", "Effusion", "Pneumonia", "Pneumothorax"], split: "patient-level 80/10/10", note: "Uncertain (-1) and not-mentioned (NaN) are both masked; the seven findings it does not carry are masked wholesale." },
  { key: "nih", name: "NIH ChestX-ray14", approxImages: "112K", labelled: 14, labels: [], split: "patient-level 80/10/10, retried until every finding has 20+ positives in val and test", note: "The only source that speaks to all fourteen channels." },
  { key: "pneumonia", name: "Pneumonia set", approxImages: "5.2K", labelled: 1, labels: ["Pneumonia"], split: "stratified", note: "One channel certain, thirteen masked. A binary corpus does not become a multi-label one by being added to the batch." },
] as const;

/** The four states a single label channel can be in for a single image. */
export const labelStates = [
  { key: "positive", label: "Positive", note: "Counted, and boosted by the positive-only class weight." },
  { key: "negative", label: "Negative", note: "Counted." },
  { key: "uncertain", label: "Uncertain", note: "CheXpert -1. Masked: contributes nothing to loss or metrics." },
  { key: "unsupported", label: "Not supplied", note: "The source does not label this finding at all. Masked." },
] as const;

